    private static byte[]? _table;

    private static byte[] Table => _table ??= Convert.FromBase64String(Packed);

    /// <summary>Unicode code point for <paramref name="cid"/>, or null when unmapped.</summary>
    internal static uint? Lookup(ushort cid)
    {
        byte[] table = Table;
        int i = cid * 2;
        if (i + 1 < table.Length)
        {
            uint unicode = (uint)((table[i] << 8) | table[i + 1]);
            if (unicode != 0) return unicode;
        }

        // Fallback: identity mapping for common Unicode ranges. Producers that emit
        // raw Unicode as the CID (rather than a collection index) land here.
        if (cid >= 0x1100 && cid <= 0x11FF) return cid; // Hangul Jamo
        if (cid >= 0x3130 && cid <= 0x318F) return cid; // Hangul Compatibility Jamo
        if (cid >= 0xAC00 && cid <= 0xD7AF) return cid; // Hangul Syllables
        if (cid >= 0xA960 && cid <= 0xA97F) return cid; // Hangul Jamo Extended-A
        if (cid >= 0xD7B0 && cid <= 0xD7FF) return cid; // Hangul Jamo Extended-B
        if (cid >= 0x4E00 && cid <= 0x9FFF) return cid; // CJK Unified Ideographs
        return null;
    }
